// Pre-procesador de fechas
const TZ = 'America/Santo_Domingo';
const now = new Date(new Date().toLocaleString('en-US', { timeZone: TZ }));
const pad = n => String(n).padStart(2, '0');
const toISO = d => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const dnames = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
const ctx = {
  hoy: toISO(now),
  manana: toISO(new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate()+1)),
  pasado_manana: toISO(new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate()+2)),
  dia_semana_hoy: dnames[now.getDay()],
  hora_actual: `${pad(now.getHours())}:${pad(now.getMinutes())}`,
  proximos_7_dias: {}
};

for (let i = 1; i <= 7; i++) {
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i);
  const n = dnames[d.getDay()];
  if (!ctx.proximos_7_dias[n])
    ctx.proximos_7_dias[n] = toISO(d);
}

return [{json: { ...$input.first().json, fecha_contexto: ctx } }];
